use std::{collections::HashMap,env,fs};
fn main(){for path in env::args().skip(1){let s=fs::read_to_string(path).unwrap();let mut freq=HashMap::<&str,usize>::new();let mut tokens=0;for token in s.split(|c:char|c.is_whitespace()){*freq.entry(token).or_default()+=1;tokens+=1;}let mut counts:Vec<_>=freq.values().copied().collect();counts.sort_unstable_by(|a,b|b.cmp(a));let head:usize=counts.iter().take(1024).sum();println!("{{\"bytes\":{},\"tokens\":{},\"unique_keys\":{},\"empty_tokens\":{},\"top1024_occurrences\":{}}}",s.len(),tokens,freq.len(),freq.get("").copied().unwrap_or(0),head);}}
